export const STATIC_DATA = [];

// Количество данных
const quantityData = 10;

function getRandomNumber(min, max) {
  return parseFloat(Math.random() * (max - min) + min).toFixed(2);
}

function getRandomInteger(min, max) {
  min = Math.ceil(min);
  max = Math.floor(max);
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

for (let i = 1; i <= quantityData; i++) {
  STATIC_DATA.push({
    id: i,
    temp: getRandomInteger(1, 50),
    pressure: getRandomInteger(1, 31),
    knns: getRandomNumber(1, 12.5),
    erosion: getRandomNumber(0.01, 0.06),
    corrosion: getRandomNumber(0.01, 0.75),
  });
}

